def digest(data): return hashlib.sha256(data).hexdigest()

def validate_cases(xml, request):
    seen = {}
    for case in ET.fromstring(xml).findall('.//testcase'):
        key = case.attrib['classname'] + '::' + case.attrib['name']
        assert key not in seen, ('duplicate', key)
        assert case.find('error') is None and case.find('failure') is None, key
        skip = case.find('skipped')
        seen[key] = (skip is not None, None if skip is None else skip.attrib.get('message'))
    assert set(seen) == set(request['required_cases']) | set(request['allowed_skips']), 'Exact identity mismatch'
    assert all(not seen[x][0] for x in request['required_cases']), 'Required case skipped'
    assert all(seen[x] == (True, reason) for x, reason in request['allowed_skips'].items())
    return {'passed': len(request['required_cases']), 'skipped': len(request['allowed_skips'])}

def main():
    repo = Path.cwd()
    out = repo / 'verification-evidence'
    out.mkdir(exist_ok=False)
    os.umask(0o022)
    tmp = Path(tempfile.mkdtemp(prefix='pr109015-', dir=os.environ['RUNNER_TEMP']))
    for name in ('home', 'hermes', 'tmp'): (tmp/name).mkdir()
    env = {k: v for k, v in os.environ.items() if not k.startswith(('HERMES_', 'PYTEST_', 'PYTHON', 'UV_')) and not any(s in k for s in ('TOKEN', 'API_KEY', 'SECRET', 'PASSWORD'))}
    env.update(HOME=str(tmp/'home'), HERMES_HOME=str(tmp/'hermes'), TMPDIR=str(tmp/'tmp'), TMP=str(tmp/'tmp'), TEMP=str(tmp/'tmp'), PYTHONPATH=str(repo), PYTHONDONTWRITEBYTECODE='1', PYTEST_DISABLE_PLUGIN_AUTOLOAD='1', TZ='UTC', LANG='C.UTF-8', PYTHONHASHSEED='0', UV_PROJECT_ENVIRONMENT=str(repo/'.venv'), GIT_CONFIG_COUNT='2', GIT_CONFIG_KEY_0='core.abbrev', GIT_CONFIG_VALUE_0='40', GIT_CONFIG_KEY_1='color.ui', GIT_CONFIG_VALUE_1='false')
    m = dict(candidate_sha=REQUEST['candidate_sha'], base_sha=REQUEST['base_sha'], provenance_kind='supervised-foreground', foreground_request_id=REQUEST['foreground_request_id'], foreground_request_sha256=REQUEST_HASH, github_run_id=os.environ.get('GITHUB_RUN_ID'), github_run_attempt=os.environ.get('GITHUB_RUN_ATTEMPT'), workflow_sha=os.environ.get('GITHUB_SHA'), github_repository=os.environ.get('GITHUB_REPOSITORY'), github_event_name=os.environ.get('GITHUB_EVENT_NAME'), github_ref=os.environ.get('GITHUB_REF'), github_workflow_ref=os.environ.get('GITHUB_WORKFLOW_REF'), wrapper_sha256=digest(Path(__file__).read_bytes()), workflow_file_sha256=digest((Path(__file__).resolve().parents[1]/'workflows/pr109015-foreground.yml').read_bytes()), umask='022', files=REQUEST['manifest'], status='running', exit_code=None, phases=[], file_sha256={}, relevant_file_sha256={})
    def save():
        p=out/'tests.json.tmp';p.write_text(json.dumps(m,indent=2)+'\n');p.replace(out/'tests.json')
    def run(name, argv, timeout=900, data=None):
        phase=dict(name=name,argv=argv,status='running',exit_code=None);m['phases'].append(phase);save()
        try:
            p=subprocess.run(argv,env=env,input=data,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=timeout)
            (out/(name+'.log')).write_bytes(p.stdout)
            phase.update(status='passed' if p.returncode==0 else 'failed',exit_code=p.returncode)
            save()
            if p.returncode: raise RuntimeError((name,p.returncode))
            return p.stdout
        except subprocess.TimeoutExpired as exc:
            data=exc.output or b''
            (out/(name+'.log')).write_bytes(data.encode() if isinstance(data,str) else data)
            phase.update(status='timeout',exit_code=None,timeout_seconds=timeout)
            m.update(status='timeout',exit_code=124);save();raise
    save()  # Before checkout validation, dependencies, or detector preflight.
    try:
        assert subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip()==REQUEST['candidate_sha']
        assert not subprocess.check_output(['git','status','--porcelain','--untracked-files=no'],text=True).strip()
        for field in ('candidate_file_sha256','relevant_file_sha256'):
            observed={p:digest((repo/p).read_bytes()) for p in REQUEST[field]}
            assert observed==REQUEST[field],field
            m['file_sha256' if field=='candidate_file_sha256' else field]=observed
        run('uv-version',['uv','--version'],60)
        assert (out/'uv-version.log').read_text().split()[:2]==['uv', REQUEST['uv_version']]
        run('dependencies',REQUEST['install_argv'],600)
        requirements=tmp/'supplement.txt';requirements.write_text(REQUEST['supplement_requirements'])
        run('supplement',['uv','pip','install','--python',str(repo/'.venv/bin/python'),'--no-deps','--only-binary',':all:','--require-hashes','-r',str(requirements)],120)
        python=str(repo/'.venv/bin/python')
        run('dependency-imports',[python,'-B','-c','import sys,pytest,pytest_asyncio,anthropic,yaml,starlette,httpx,openai; assert sys.version_info[:3]==(3,14,4); print(sys.version)'],60)
        run('preflight',[python,'-B','-c','import os,json; from pathlib import Path; from hermes_constants import _detect_container; c=_detect_container(); print(json.dumps(dict(container=c,dockerenv=Path("/.dockerenv").exists(),containerenv=Path("/run/.containerenv").exists(),uid=os.getuid()))); assert os.name=="posix" and not c and not Path("/.dockerenv").exists() and not Path("/run/.containerenv").exists(), "Requires genuine non-container POSIX VM"'],60)
        pack=base64.b64decode(HISTORICAL_PACK)
        assert digest(pack)==REQUEST['historical_pack_sha256']
        run('historical-objects',['git','index-pack','--stdin'],120,pack)
        root=ET.Element('testsuites')
        for i,command in enumerate(REQUEST['commands']):
            command=list(command)
            if command[0]=='python':
                command[0]=python
                command+=['-p','pytest_asyncio.plugin','--basetemp',str(tmp/f'pytest-{i}'),'--junitxml',str(out/f'case-{i}.xml')]
            output=run(f'command-{i}',command,900)
            if command[:2]==['git','range-diff']:
                assert digest(output)==REQUEST['range_diff_sha256'][str(i)],'Historical preservation output mismatch'
            if command[0]==python:
                tree=ET.parse(out/f'case-{i}.xml').getroot()
                for case in tree.findall('.//testcase'): root.append(case)
        xml=ET.tostring(root,encoding='utf-8',xml_declaration=True)
        (out/'junit.xml').write_bytes(xml)
        m['cases']=validate_cases(xml,REQUEST)
        m.update(status='passed',exit_code=0)
    except Exception as exc:
        if m['status']!='timeout':m.update(status='failed',exit_code=1)
        m['error']=str(exc)
    finally:
        p=subprocess.run(['git','diff','--exit-code',REQUEST['candidate_sha'],'--'],stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
        (out/'integrity.log').write_bytes(p.stdout);m['integrity_exit_code']=p.returncode
        if p.returncode:m.update(status='integrity_failed',exit_code=1)
        m['log_sha256_by_file']={p.name:digest(p.read_bytes()) for p in out.iterdir() if p.name!='tests.json' and p.is_file()}
        save()
    return m['exit_code']

if __name__=='__main__':sys.exit(main())
